-- ============================================================================
-- 030: which firmware generation each registry parameter belongs to
-- ----------------------------------------------------------------------------
-- nano_registry holds the old Gen 2 Nano parameters (nano_iot_firmware) and
-- NanoV3's side by side, so the Config tab showed apparent duplicates such as
-- P-3020 (Gen 2 Battery System Voltage) next to P-5021 (NanoV3's). The new
-- generations column lets the Config tab show one generation at a time.
--
-- GENERATED by parsing both firmware config tables; do not hand-edit the lists:
--   NanoV3 components/config_manager/config_table.c @ 59839f0: 207 params
--   Gen 2  components/config_manager/config_table.c @ a6ea1b6: 284 params
--   shared IDs: 53
-- A registry row in neither table counts as Gen 2. Rows added later without a
-- value are classified by the API from their source column.
-- Re-runnable.
-- ============================================================================

ALTER TABLE nano_registry ADD COLUMN IF NOT EXISTS generations text[];

UPDATE nano_registry SET generations = CASE
  WHEN pid = ANY (ARRAY[
    'P-104', 'P-107', 'P-108', 'P-109', 'P-401', 'P-501', 'P-502', 'P-503', 'P-504', 'P-505', 'P-506', 'P-509',
    'P-510', 'P-513', 'P-514', 'P-602', 'P-603', 'P-604', 'P-609', 'P-802', 'P-803', 'P-809', 'P-810', 'P-1101',
    'P-1301', 'P-1302', 'P-1303', 'P-1306', 'P-1308', 'P-1501', 'P-1502', 'P-3026', 'P-4061', 'P-4062', 'P-4063', 'P-4075',
    'P-4093', 'P-4096', 'P-4097', 'P-4098', 'P-4100', 'P-4101', 'P-4104', 'P-4105', 'P-4106', 'P-4107', 'P-4108', 'P-4200',
    'P-4201', 'P-4203', 'P-4204', 'P-4300', 'P-4302'
  ]) THEN '{NanoV3,Gen2}'::text[]
  WHEN pid = ANY (ARRAY[
    'P-515', 'P-4110', 'P-4111', 'P-4112', 'P-4113', 'P-4114', 'P-4115', 'P-4116', 'P-4117', 'P-4118', 'P-4119', 'P-4120',
    'P-4121', 'P-4122', 'P-4123', 'P-4124', 'P-4125', 'P-4126', 'P-4127', 'P-4128', 'P-4129', 'P-4130', 'P-4131', 'P-4132',
    'P-4133', 'P-4134', 'P-4135', 'P-4136', 'P-4137', 'P-4138', 'P-4139', 'P-4140', 'P-4141', 'P-4142', 'P-4143', 'P-4150',
    'P-4151', 'P-4152', 'P-4153', 'P-4154', 'P-4155', 'P-4156', 'P-4157', 'P-4206', 'P-4210', 'P-4211', 'P-4212', 'P-4213',
    'P-4214', 'P-4215', 'P-4218', 'P-4220', 'P-4221', 'P-4222', 'P-4223', 'P-4224', 'P-4225', 'P-4230', 'P-4231', 'P-4232',
    'P-4233', 'P-4234', 'P-4235', 'P-4236', 'P-4237', 'P-4240', 'P-4241', 'P-4242', 'P-4243', 'P-4244', 'P-4245', 'P-4246',
    'P-4247', 'P-5001', 'P-5002', 'P-5003', 'P-5005', 'P-5006', 'P-5007', 'P-5010', 'P-5011', 'P-5012', 'P-5020', 'P-5021',
    'P-5022', 'P-5023', 'P-5024', 'P-5025', 'P-5026', 'P-5027', 'P-5028', 'P-5029', 'P-5030', 'P-5040', 'P-5041', 'P-5042',
    'P-5100', 'P-5101', 'P-5102', 'P-5103', 'P-5104', 'P-5105', 'P-5106', 'P-5107', 'P-5108', 'P-5109', 'P-5110', 'P-5111',
    'P-5112', 'P-5113', 'P-5114', 'P-5200', 'P-5201', 'P-5202', 'P-5206', 'P-5207', 'P-5208', 'P-5209', 'P-5250', 'P-5251',
    'P-5300', 'P-5301', 'P-5302', 'P-5303', 'P-5304', 'P-5400', 'P-5401', 'P-5402', 'P-5500', 'P-5501', 'P-5502', 'P-5503',
    'P-5504', 'P-5505', 'P-5506', 'P-5507', 'P-5508', 'P-5600', 'P-5601', 'P-5602', 'P-5603', 'P-5604', 'P-5605', 'P-5700',
    'P-5701', 'P-5702', 'P-5703', 'P-5704', 'P-5705', 'P-5706', 'P-5707', 'P-5708', 'P-5709', 'P-5710'
  ]) THEN '{NanoV3}'::text[]
  ELSE '{Gen2}'::text[]
END;

DO $$
DECLARE n_both integer; n_v3 integer; n_g2 integer; n_null integer;
BEGIN
  SELECT count(*) FILTER (WHERE generations = '{NanoV3,Gen2}'),
         count(*) FILTER (WHERE generations = '{NanoV3}'),
         count(*) FILTER (WHERE generations = '{Gen2}'),
         count(*) FILTER (WHERE generations IS NULL)
    INTO n_both, n_v3, n_g2, n_null
    FROM nano_registry;
  IF n_null > 0 THEN
    RAISE EXCEPTION 'nano_registry: % row(s) left without generations', n_null;
  END IF;
  IF n_both + n_v3 = 0 THEN
    RAISE EXCEPTION 'nano_registry: no NanoV3 parameters found; is this the right database?';
  END IF;
  RAISE NOTICE 'nano_registry generations: % NanoV3 only, % Gen 2 only, % both (firmware tables: 154 / 231 / 53)',
    n_v3, n_g2, n_both;
END $$;
